    sheet(wb,'部门计分明细',[['计分行编号','部门','分数','原自动分','计算依据','关联明细'],...r.departments.map(l=>[l.id,l.target,l.score,l.originalScore??'',l.explanation,l.recordIds.join('、')])],[42,20,12,12,75,45]);
